quiz.question:
What will be the output of the following code if the temperature is 50?
 let temperature = 50;
 if (temperature > 70) {
   console.log('It’s a warm day.');
 } else {
   console.log('It’s a chilly day.');
 }

What will be the output of this JavaScript code?
 let fruit = 'banana';
 switch (fruit) {
   case 'banana':
     console.log('Banana selected');
     break;
   case 'apple':
     console.log('Apple selected');
     break;
   default:
     console.log('Fruit not found');
 }

What will the following code output?
 for (let i = 0; i < 3; i++) {
   console.log('Count: ' + i);
 }

